// src/ads/RpcAdsApi.ts
var RpcAdsApi = class {
  rpcClient;
  constructor(rpcClient) {
    this.rpcClient = rpcClient;
  }
  async showInterstitialAd(options) {
    const response = await this.rpcClient.call(
      "H5_SHOW_INTERSTITIAL_AD" /* SHOW_INTERSTITIAL_AD */,
      options || {},
      -1
    );
    return response.shown;
  }
  async isInterstitialAdReadyAsync() {
    const response = await this.rpcClient.call(
      "H5_IS_INTERSTITIAL_AD_READY" /* IS_INTERSTITIAL_AD_READY */
    );
    return response.ready;
  }
  async isRewardedAdReadyAsync() {
    const response = await this.rpcClient.call(
      "H5_IS_REWARDED_AD_READY" /* IS_REWARDED_AD_READY */
    );
    return response.ready;
  }
  async showRewardedAdAsync(options) {
    const result = await this.rpcClient.call(
      "H5_SHOW_REWARDED_AD" /* SHOW_REWARDED_AD */,
      options || {},
      -1
    );
    return result.rewardEarned;
  }
};

// src/MockDebug.ts
var MockDebug = { enabled: false };
function mockLog(tag, message, ...args) {
  if (MockDebug.enabled) console.log(`[${tag}] ${message}`, ...args);
}

// src/ads/MockAdsApi.ts
var TAG = "Mock Ads";
var MockAdsApi = class {
  mockOverlay;
  constructor(mockOverlay) {
    this.mockOverlay = mockOverlay;
  }
  async isRewardedAdReadyAsync() {
    mockLog(TAG, "isRewardedAdReadyAsync \u2192 true");
    await createMockDelay(MOCK_DELAYS.short);
    return true;
  }
  async isInterstitialAdReadyAsync() {
    mockLog(TAG, "isInterstitialAdReadyAsync \u2192 true");
    await createMockDelay(MOCK_DELAYS.short);
    return true;
  }
  async showRewardedAdAsync(options) {
    mockLog(TAG, "showRewardedAdAsync");
    await this.mockOverlay.showAdOverlay("rewarded", options);
    return true;
  }
  async showInterstitialAd(options) {
    mockLog(TAG, "showInterstitialAd");
    await this.mockOverlay.showAdOverlay("interstitial", options);
    return true;
  }
};

// src/ads/index.ts
function initializeAds(rundotGameApiInstance, host) {
  rundotGameApiInstance.isRewardedAdReadyAsync = host.ads.isRewardedAdReadyAsync.bind(host.ads);
  rundotGameApiInstance.showRewardedAdAsync = host.ads.showRewardedAdAsync.bind(
    host.ads
  );
  rundotGameApiInstance.ads = host.ads;
}

// src/ai/AiApi.ts
function toPromptWireRequest(request) {
  return { promptId: request.promptId, input: request.input };
}

