    const isProtected = typeof entry === "object" && entry.protected === true;
    if (isProtected) {
      throw new Error(
        `[RUN] Asset "${normalizedPath}" requires entitlement validation. Update the Client App to a version that supports CDN entitlements.`
      );
    }
    const extensionMatch = normalizedPath.match(/\.([^.]+)$/);
