// src/iap/IapApi.ts
var TIER_SUPPORTED_INTERVALS = {
  LITE: ["weekly"],
  CORE: ["weekly", "monthly", "annual"],
  PLUS: ["weekly", "monthly", "annual"],
  PRIME: ["weekly", "monthly", "annual"],
  ULTIMATE: ["weekly", "monthly", "annual"]
};
function assertTierSupportsInterval(tier, interval) {
  const supported = TIER_SUPPORTED_INTERVALS[tier];
  if (!supported?.includes(interval)) {
    throw new RundotApiError(
      "UNSUPPORTED_SUBSCRIPTION_INTERVAL",
      `The ${tier} subscription tier does not offer a ${interval} interval. Available interval(s): ${supported?.join(", ") || "none"}.`
    );
  }
}

