// src/access-gate/AccessTier.ts
var AccessDeniedError = class extends Error {
  requiredTier;
  action;
  constructor(requiredTier, action) {
    super(`[RUN] Access denied. Required tier: ${requiredTier}. Action: ${action}`);
    this.name = "AccessDeniedError";
    this.requiredTier = requiredTier;
    this.action = action;
  }
};

// src/access-gate/createAccessGatedApi.ts
function createAccessGatedApi(api, gatedMethods, requiredTier, config) {
  const gatedSet = new Set(gatedMethods);
  return new Proxy(api, {
    get(target, prop, receiver) {
      const value = Reflect.get(target, prop, receiver);
      if (!gatedSet.has(prop) || typeof value !== "function") {
        return value;
      }
      return function gatedCall(...args) {
        if (!config.isAnonymous()) {
          return value.apply(target, args);
        }
        const action = "prompt_login";
        if (!config.isAutoPromptEnabled()) {
          return Promise.reject(new AccessDeniedError(requiredTier, action));
        }
        return (async () => {
          const loginResult = await config.promptLogin();
          if (!loginResult.success) {
            throw new AccessDeniedError(requiredTier, action);
          }
          return value.apply(target, args);
        })();
      };
    }
  });
}

// src/access-gate/gateStreaming.ts
function gateStreaming(streamFn, config, requiredTier = "authenticated_18plus") {
  return (...args) => ({
    async *[Symbol.asyncIterator]() {
      if (config.isAnonymous()) {
        if (!config.isAutoPromptEnabled()) {
          throw new AccessDeniedError(requiredTier, "prompt_login");
        }
        const result = await config.promptLogin();
        if (!result.success) {
          throw new AccessDeniedError(requiredTier, "prompt_login");
        }
      }
      yield* streamFn(...args);
    }
  });
}

// src/access-gate/applyAccessGates.ts
function applyAccessGates(host) {
  const gateConfig = {
    isAnonymous: () => host.accessGate.isAnonymous(),
    promptLogin: () => host.accessGate.promptLogin(),
    isAutoPromptEnabled: () => host.accessGate.autoPromptLogin
  };
  const baseTextGen = host.textGen;
  const gatedStream = gateStreaming(
    (request, options) => baseTextGen.requestChatCompletionStreamAsync(request, options),
    gateConfig
  );
  const gatedPromptStream = gateStreaming(
    (request, options) => baseTextGen.requestPromptCompletionStreamAsync(request, options),
    gateConfig
  );
  const gatedTextGen = createAccessGatedApi(
    baseTextGen,
    ["requestChatCompletionAsync", "requestPromptCompletionAsync", "getAvailableCompletionModels"],
    "authenticated_18plus",
    gateConfig
  );
  host.textGen = new Proxy(gatedTextGen, {
    get(target, prop, receiver) {
      if (prop === "requestChatCompletionStreamAsync") {
        return gatedStream;
      }
      if (prop === "requestPromptCompletionStreamAsync") {
        return gatedPromptStream;
      }
      return Reflect.get(target, prop, receiver);
    }
  });
  host.imageGen = createAccessGatedApi(
    host.imageGen,
    ["generate", "estimateDepth", "removeBackground"],
    "authenticated_18plus",
    gateConfig
  );
  host.audioGen = createAccessGatedApi(
    host.audioGen,
    ["generate", "designVoices", "saveDesignedVoice"],
    "authenticated_18plus",
    gateConfig
  );
  host.spriteGen = createAccessGatedApi(
    host.spriteGen,
    ["generate", "animate"],
    "authenticated_18plus",
    gateConfig
  );
  host.threeDGen = createAccessGatedApi(
    host.threeDGen,
    ["generate", "remesh", "rig", "animate"],
    "authenticated_18plus",
    gateConfig
  );
  host.ugc = createAccessGatedApi(
    host.ugc,
    ["create", "update", "delete", "like", "unlike", "report"],
    "authenticated_18plus",
    gateConfig
  );
  host.rooms = createAccessGatedApi(
    host.rooms,
    [
      "createRoomAsync",
      "joinOrCreateRoomAsync",
      "joinRoomByCodeAsync",
      "getUserRoomsAsync",
      "subscribeAsync",
      "updateRoomDataAsync",
      "getRoomDataAsync",
      "sendRoomMessageAsync",
      "leaveRoomAsync",
      "kickPlayerAsync",
      "startRoomGameAsync",
      "proposeMoveAsync",
      "validateMoveAsync"
    ],
    "authenticated_18plus",
    gateConfig
  );
  host.multiplayer = createAccessGatedApi(
    host.multiplayer,
    ["createRoom", "joinOrCreateRoom", "joinRoomByCode", "getUserRooms"],
    "authenticated_18plus",
    gateConfig
  );
}

// src/access-gate/RpcAccessGateApi.ts
var RpcAccessGateApi = class {
  constructor(rpcClient, rundotGameApi) {
    this.rpcClient = rpcClient;
    this.rundotGameApi = rundotGameApi;
  }
  rpcClient;
  rundotGameApi;
  autoPromptLogin = true;
  // Coalesces concurrent prompts: N gated calls hitting the auth wall at once
  // share one host overlay/RPC instead of stacking N login prompts.
  inFlightLogin = null;
  getAccessTier() {
    const profile = this.rundotGameApi._profileData;
    if (!profile || profile.isAnonymous) {
      return "anonymous";
    }
    return "authenticated_18plus";
  }
  isAnonymous() {
    return this.getAccessTier() === "anonymous";
  }
  async promptLogin() {
    if (this.inFlightLogin) {
      return this.inFlightLogin;
    }
    this.inFlightLogin = this.doPromptLogin().finally(() => {
      this.inFlightLogin = null;
    });
    return this.inFlightLogin;
  }
  async doPromptLogin() {
    const result = await this.rpcClient.call(
      "H5_PROMPT_LOGIN" /* H5_PROMPT_LOGIN */,
      {},
      -1
    );
    if (result.success && result.profile) {
      this.rundotGameApi._profileData = sanitizeProfile(result.profile);
    }
    return result;
  }
};

